export function initFamily(c){const {$,state,table,req,element,button,busy,toast}=c;const action=(a,p={})=>req('/rest/v1/rpc/family_action',{method:'POST',body:{action:a,payload:p}});let options=[];
 document.addEventListener('family:tenant-selected',()=>loadOptions().catch(()=>{}));
 async function loadOptions(){options=state.user?await table('kinship_options','select=*&order=generation,label'):await req('/rest/v1/rpc/tenant_kinship',{method:'POST',auth:false,body:{code:JSON.parse(localStorage.getItem('family-selection')||'null')?.code||'01'}});options=options.map(o=>({...o,enabled:o.enabled??true,for_reference:o.for_reference??true}));for(const prefix of ['signup','profile']){const select=$(prefix+'-relation'),value=select.value;select.replaceChildren(element('option','اختر…'));select.firstChild.value='';for(const o of options.filter(o=>o.enabled&&o.for_reference||o.code===value)){const item=element('option',o.label);item.value=o.code;select.append(item);}select.value=value;}}
 loadOptions().catch(()=>toast('تعذّر تحميل خيارات القرابة. حاول تحديث الصفحة.'));
 for(const prefix of ['signup','profile']){const input=$(prefix+'-ref'),box=element('div',undefined,'reference-results');input.after(box);input.placeholder='الاسم أو بداية رقم الجوال';let timer,version=0;input.addEventListener('input',()=>{clearTimeout(timer);const n=++version;timer=setTimeout(async()=>{box.replaceChildren();if(!input.value.trim())return;if(!state.user){box.append(element('small','يمكن البحث عن المعرّف من حسابك بعد تأكيد البريد. أدخل اسمه الرباعي الآن.'));return;}try{const rows=await action('referees',{term:input.value.trim()});if(n!==version)return;for(const p of rows)box.append(button(p.display_name,()=>{input.value=p.display_name;box.replaceChildren();},'chat-contact'));if(!rows.length)box.append(element('small','لا توجد أسماء مطابقة.'));}catch(e){box.textContent=e.message;}},180);});}
 const open=button('♧ شجرة عائلتي والأسماء المشابهة',tree,'secondary');open.id='family-tree-open';$('profile-dialog').append(open);
 function dialog(title){const d=element('dialog');d.className='family-dialog';d.append(element('h2',title),button('✕ إغلاق',()=>{d.close();d.remove();},'dialog-close text-button'));document.body.append(d);d.showModal();return d;}
 async function tree(){
 if(state.profile.status!=='active')throw Error('شجرة العائلة للأعضاء المعتمدين.');await loadOptions();const d=dialog('شجرة عائلتي');d.classList.add('family-tree-dialog');
 d.append(element('p','أجيال تجمعنا · القرابة المقترحة تحتاج تأكيد الطرف الآخر أو مدير العائلة لفتح استثناء الدردشة.','tree-intro'));
 const chart=element('div',undefined,'family-tree'),trusted=element('div',undefined,'trusted-grid'),requests=element('div'),suggest=element('div');
 const search=element('input');search.placeholder='ابحث عن قريب بالاسم أو رقم الجوال';search.setAttribute('aria-label',search.placeholder);const matches=element('div');d.append(chart,element('h3','الأعضاء الذين عرّفتهم أو عرّفوك'),trusted,element('h3','طلبات تأكيد القرابة'),requests,element('h3','إضافة قريب'),search,matches,element('h3','اقتراحات تشابه الأسماء · ٧٠٪ أو أكثر'),suggest);
 async function avatar(p,node){const pic=element('span',p.display_name?.slice(0,1)||'♙','tree-avatar');node.prepend(pic);if(p.avatar_path)try{const path=p.avatar_path.split('/').map(encodeURIComponent).join('/');const r=await req('/storage/v1/object/sign/profile-images/'+path,{method:'POST',body:{expiresIn:600}});if(!d.isConnected)return;const img=element('img');img.src='https://dlkykiducjimwehfhxfq.supabase.co/storage/v1'+r.signedURL;img.alt='صورة '+p.display_name;pic.replaceChildren(img)}catch{}}
 function person(p,relation,canChat=true){const node=element('article',undefined,'tree-person');node.append(element('strong',p.display_name),element('small',relation||''));avatar(p,node);if(p.id!==state.user.id){const chat=button('◌ تواصل بالخاص',()=>document.dispatchEvent(new CustomEvent('family:chat',{detail:{id:p.id,onOpened:()=>{d.close();d.remove()}}})),'tree-chat');chat.disabled=!canChat;chat.title=canChat?'فتح الدردشة الخاصة':'التواصل غير متاح وفق ضوابط العائلة';node.append(chat)}return node}
 function candidate(p,box){const row=person(p,p.score?'تشابه '+p.score+'٪':'حدد القرابة',false);row.querySelector('.tree-chat')?.remove();const select=element('select');select.setAttribute('aria-label','قرابة '+p.display_name);const empty=element('option','اختر صلة القرابة');empty.value='';select.append(empty);for(const o of options.filter(o=>o.enabled)){const op=element('option',o.label);op.value=o.code;select.append(op)}const add=button('إضافة وطلب تأكيد',()=>busy(add,async()=>{if(!select.value)throw Error('اختر صلة القرابة.');await action('link',{member:p.id,relation:select.value});await render();toast('أضيفت القرابة وأرسل طلب التأكيد.')}),'secondary');add.disabled=!!state.readOnly;row.append(select,add);box.append(row)}
 let timer,version=0;search.oninput=()=>{clearTimeout(timer);const v=++version;timer=setTimeout(async()=>{try{const rows=await action('find_relative',{term:search.value.trim()});if(v!==version||!d.isConnected)return;matches.replaceChildren();for(const p of rows)candidate(p,matches)}catch(e){toast(e.message)}},220)};
 async function render(){const [links,known,pending]=await Promise.all([action('tree'),action('trusted'),action('kinship_requests')]);if(!d.isConnected)return;chart.replaceChildren();trusted.replaceChildren();requests.replaceChildren();const levels=[...new Set([0,...links.map(r=>r.generation)])].sort((a,b)=>a-b);for(const level of levels){const band=element('section',undefined,'tree-level');band.append(element('h4',level<0?'الأصول · الجيل '+Math.abs(level):level>0?'الفروع · الجيل '+level:'العائلة · جيلي'));const nodes=element('div',undefined,'tree-nodes');if(level===0){const self=person({...state.profile,id:state.user.id},'أنا');self.classList.add('self');nodes.append(self)}for(const p of links.filter(p=>p.generation===level)){const node=person(p,p.label,p.can_chat);node.append(element('span',p.confirmed?'✓ قرابة مؤكدة':'بانتظار تأكيد القرابة',p.confirmed?'kinship-confirmed':'kinship-pending'));const remove=button('إزالة العلاقة',()=>busy(remove,async()=>{await action('unlink',{member:p.id});await render()}),'text-button');remove.disabled=!!state.readOnly;node.append(remove);nodes.append(node)}band.append(nodes);chart.append(band)}for(const p of known)trusted.append(person(p,'تعريف مقبول',p.can_chat));if(!known.length)trusted.append(element('p','لا توجد علاقات تعريف مقبولة بعد.','muted'));for(const p of pending){const row=person(p,'طلب '+p.label,false);row.querySelector('.tree-chat')?.remove();const accept=button('تأكيد القرابة',()=>busy(accept,async()=>{await action('confirm_link',{owner:p.id});await render()}),'primary'),reject=button('رفض',()=>busy(reject,async()=>{await action('reject_link',{owner:p.id});await render()}),'text-button');accept.disabled=reject.disabled=!!state.readOnly;row.append(accept,reject);requests.append(row)}if(!pending.length)requests.append(element('p','لا توجد طلبات قرابة تنتظر تأكيدك.','muted'))}
 await render();for(const p of await action('similar'))candidate(p,suggest);
 }
 const kinshipReview=button('طلبات تأكيد القرابة',async()=>{const d=dialog('طلبات تأكيد القرابة');const list=element('div');d.append(list);async function refresh(){list.replaceChildren();for(const r of await action('admin_kinship_list')){const row=element('div',undefined,'maintenance-request');row.append(element('p',r.display_name+' · '+r.label+' · '+r.member_name));for(const [act,label]of [['admin_kinship_confirm','أؤكد صحة القرابة'],['admin_kinship_reject','رفض']]){const b=button(label,()=>busy(b,async()=>{await action(act,{owner:r.owner_id,member:r.member_id});await refresh()}),'secondary');row.append(b)}list.append(row)}}await refresh()},'secondary');$('settings-section').append(kinshipReview);
 const form=element('form');form.id='kinship-admin';form.innerHTML='<h3>خيارات صلة القرابة</h3><p class="muted">تحدد الجيل بالنسبة للمستخدم: الأب −1، الجد −2، الأخ أو الزوج 0، الابن 1. تعطيل الخيار يمنع اختياره الجديد ويحافظ على القرابات السابقة.</p><label>اسم صلة القرابة<input name="label" required maxlength="60"></label><label>ترتيب الجيل<input name="generation" type="number" min="-4" max="4" value="0" required></label><label class="inline"><input name="reference" type="checkbox"> متاح لاختيار المعرّف للأنثى</label><button class="secondary">إضافة خيار قرابة</button><div id="kinship-list"></div>';const adminList=$('kinship-list')||form.querySelector('#kinship-list');adminList.remove();$('settings-section').append(form,adminList);form.onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await table('kinship_options','',{method:'POST',body:{code:'relation_'+crypto.randomUUID().replaceAll('-','').slice(0,20),label:form.elements.label.value.trim(),generation:Number(form.elements.generation.value),for_reference:form.elements.reference.checked}});form.reset();await admin();toast('تمت إضافة خيار القرابة.');});};
 async function admin(){await loadOptions();const list=$('kinship-list');list.replaceChildren();for(const o of options){const f=element('form',undefined,'activity-row'),name=element('input'),generation=element('input'),ref=element('input'),enabled=element('input'),chat=element('input');name.value=o.label;name.required=true;name.maxLength=60;name.setAttribute('aria-label','اسم القرابة');generation.type='number';generation.min=-4;generation.max=4;generation.required=true;generation.value=o.generation;generation.setAttribute('aria-label','ترتيب الجيل');ref.type=enabled.type=chat.type='checkbox';chat.checked=o.allow_private_chat;ref.checked=o.for_reference;enabled.checked=o.enabled;const a=element('label','متاح للمُعرّف','inline'),b=element('label','مفعّل','inline');a.append(ref);b.append(enabled);const save=element('button','حفظ','secondary');const chatLabel=element('label','استثناء الدردشة بعد تأكيد القرابة','inline');chatLabel.append(chat);f.append(name,generation,a,b,chatLabel,save);f.onsubmit=e=>{e.preventDefault();e.stopPropagation();busy(save,async()=>{await table('kinship_options','code=eq.'+o.code,{method:'PATCH',body:{label:name.value.trim(),generation:Number(generation.value),for_reference:ref.checked,enabled:enabled.checked,allow_private_chat:chat.checked}});await admin();toast('تم تحديث خيار القرابة.');});};list.append(f);}}
 return {admin,loadOptions};
}
